-- ============================================================================
-- TBS Phase 4: Noble Sivrn sphinx arc + Efreeti Death Visage
-- Generated by hand (2026-09-20).
--
-- Five solo tasks (620070-620074) offered in order by Noble Sivrn
-- (#Noble_Sivrn, 418049) in the Jewel of Atiiki, followed by the
-- Efreeti Death Visage task (620075), which awards Platinum Efreeti Mask
-- (79507) from Sivrn and, after the player assembles the armor set, the
-- Token of Order (79508), and the mask, spawns Paza (423914) at
-- Mahatototarit's board. Paza awards Efreeti Death Visage (79515);
-- Xanxionusus (418075) awards Paza's Cursed Remains (79516) to
-- necromancers. All 79500-79508 drops already exist on Atiiki efreeti.
-- ============================================================================

DELETE FROM `task_activities` WHERE `taskid` BETWEEN 620070 AND 620075;
DELETE FROM `tasks` WHERE `id` BETWEEN 620070 AND 620075;

